PORT = 8000
MAX_RETRIES = 3
TIMEOUT = 2

# Known constants
KNOWN_PREFIX = b'flag{'
BLOCK_SIZE = 16  # Common AES block size
CHARSET = (string.ascii_letters + string.digits + '_' + '}').encode()

def connect_with_retry():
    for _ in range(MAX_RETRIES):
        try:
            r = remote(HOST, PORT, timeout=TIMEOUT)
            r.recvuntil(b'?', timeout=TIMEOUT)
            return r
        except Exception as e:
            log.warning(f"Connection failed: {e}")
            time.sleep(1)
    raise Exception("Failed to connect after retries")

def get_oracle_response(r, payload):
    try:
        r.sendline(payload.hex().encode())
        response = r.recvline(timeout=TIMEOUT).strip()
        try:
            return bytes.fromhex(response.decode())
        except:
            return None
    except EOFError:
        return None
    except Exception as e:
        return None

def find_flag():
    log.info("Starting ECB oracle attack...")

    known_bytes = bytearray(KNOWN_PREFIX)
    found_chars = set()

    while b'}' not in known_bytes[-1:] and len(known_bytes) < 50:
        r = connect_with_retry()

        # Calculate padding to align blocks
        padding_size = BLOCK_SIZE - (len(known_bytes) % BLOCK_SIZE)
        padding = b'A' * padding_size

        # Get reference ciphertext
        base_payload = padding + known_bytes
        reference = get_oracle_response(r, base_payload)

        if not reference:
            r.close()
            continue

        found = False
        # First try characters that worked before
        for c in sorted(found_chars) + [b'}'[0]]:
            test_payload = padding + known_bytes + bytes([c])
            response = get_oracle_response(r, test_payload)

            if response and response[:BLOCK_SIZE] == reference[:BLOCK_SIZE]:
                known_bytes.append(c)
                found_chars.add(c)
                log.info(f"Found character: {chr(c)}")
                log.info(f"Current flag: {known_bytes.decode()}")
                found = True
                break

        # If no match found, try all other characters
        if not found:
            for c in CHARSET:
                if c in found_chars or c == b'}'[0]:
                    continue

                test_payload = padding + known_bytes + bytes([c])
                response = get_oracle_response(r, test_payload)

                if response and response[:BLOCK_SIZE] == reference[:BLOCK_SIZE]:
                    known_bytes.append(c)
                    found_chars.add(c)
                    log.info(f"Found character: {chr(c)}")
                    log.info(f"Current flag: {known_bytes.decode()}")
                    found = True
                    break

        r.close()
        if not found:
            log.warning("No character found, retrying...")
            time.sleep(0.5)

    return known_bytes.decode()

def main():
    context.log_level = 'info'
    try:
        flag = find_flag()
        log.success(f"Found flag: {flag}")
    except Exception as e:
        log.error(f"Attack failed: {e}")

